using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Academy.Api.Auth;
using Academy.Api.Slice5;
using Academy.Infrastructure.Persistence;
using Academy.Infrastructure.Evaluations;
using Academy.Infrastructure.Tenancy;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace Academy.IntegrationTests;
public sealed partial class BrandingMatchesTests
{
    [Fact]public async Task Lesson_archive_requires_global_library_edit_and_revocation_precedes_replay()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
        var f=await LessonFixture(db,group);var ex=await LessonId(await Send(owner,Lessons+"/exercises",ExerciseBody(f.Level)));var v=await db.TrainingExercises.Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();var body=new LessonArchiveWrite(v,null,Guid.NewGuid());var path=$"{Lessons}/exercises/{ex}/archive";var grant=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="evaluations");var old=grant==null?null:JsonSerializer.Serialize(grant);grant??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="evaluations"};if(old==null)db.StaffActionGrants.Add(grant);var membership=await db.AcademyMemberships.SingleAsync(m=>m.Id==member);
        try{grant.IsActive=true;grant.Read=true;grant.Add=true;grant.Edit=true;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,path,body)).StatusCode);membership.AllBranches=true;grant.Edit=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,path,body)).StatusCode);grant.Add=false;grant.Edit=true;await db.SaveChangesAsync();await LessonId(await Send(admin,path,body));grant.Edit=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,path,body)).StatusCode);grant.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(Lessons+"/library")).StatusCode);}
        finally{membership.AllBranches=false;if(old==null)db.StaffActionGrants.Remove(grant);else db.Entry(grant).CurrentValues.SetValues(JsonSerializer.Deserialize<StaffActionGrant>(old)!);await db.SaveChangesAsync();}
    });
    [Fact]public async Task Lesson_archive_preserves_assigned_source_blocks_new_use_and_allows_explicit_new_version_without_money_or_attendance_change()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var f=await LessonFixture(db);
        var ex=await LessonId(await Send(owner,Lessons+"/exercises",ExerciseBody(f.Level)));var ev=await db.TrainingExercises.Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,true,Guid.NewGuid()))).EnsureSuccessStatusCode();var make=new LessonTemplateWrite(f.Level,"خطة أرشفة اصطناعية",60,[new(ex,60)],Guid.NewGuid());var p=await LessonId(await Send(owner,Lessons+"/templates",make));var v=(await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{p}")).GetProperty("item").GetProperty("version").GetUInt32();(await Send(owner,$"{Lessons}/templates/{p}/review",new LessonReview(v,true,Guid.NewGuid()))).EnsureSuccessStatusCode();var assign=new LessonAssign(p,0,Guid.NewGuid());await LessonId(await Send(owner,$"{Lessons}/sessions/{f.Session}",assign));
        var before=await coach.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}");var money=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");var attendance=await db.PlayerAttendances.CountAsync();var notices=await db.AcademyNotices.CountAsync();ev=await db.TrainingExercises.AsNoTracking().Where(e=>e.Id==ex).Select(e=>e.Version).SingleAsync();var body=new LessonArchiveWrite(ev,null,Guid.NewGuid());var path=$"{Lessons}/exercises/{ex}/archive";
        Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync(path,body)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,path,body)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,path,body)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(foreign,path,body)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,path,body with{Version=ev+1})).StatusCode);
        var archive=await LessonId(await Send(owner,path,body));Assert.Equal(archive,await LessonId(await Send(owner,path,body)));Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,path,body with{Note="نفس المفتاح مختلف"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,path,body with{RequestId=Guid.NewGuid()})).StatusCode);
        var after=await coach.GetFromJsonAsync<JsonElement>($"{Lessons}/sessions/{f.Session}");Assert.Equal(before.GetProperty("revision").GetInt32(),after.GetProperty("revision").GetInt32());Assert.Equal(before.GetProperty("history").GetRawText(),after.GetProperty("history").GetRawText());Assert.Equal(p,after.GetProperty("active").GetProperty("item").GetProperty("id").GetGuid());Assert.True(after.GetProperty("active").GetProperty("contentRetired").GetBoolean());Assert.Equal("تمرين اصطناعي أصلي",after.GetProperty("active").GetProperty("steps")[0].GetProperty("exercise").GetProperty("title").GetString());Assert.Empty(after.GetProperty("available").EnumerateArray());Assert.Equal(1,await db.SessionLessonAssignments.CountAsync(a=>a.TrainingSessionId==f.Session));
        var library=await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/library?levelId={f.Level}");Assert.Empty(library.GetProperty("exercises").EnumerateArray());Assert.Empty(library.GetProperty("templates").EnumerateArray());var archived=await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/library?levelId={f.Level}&includeArchived=true");Assert.Single(archived.GetProperty("exercises").EnumerateArray());Assert.Equal(HttpStatusCode.Forbidden,(await coach.GetAsync(Lessons+"/library?includeArchived=true")).StatusCode);
        Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,Lessons+"/templates",make with{RequestId=Guid.NewGuid()})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Lessons}/exercises/{ex}/review",new LessonReview(ev,true,Guid.NewGuid()))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Lessons}/templates/{p}/review",new LessonReview(v,true,Guid.NewGuid()))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(owner,$"{Lessons}/sessions/{f.Session}",new LessonAssign(p,1,Guid.NewGuid()))).StatusCode);await LessonId(await Send(owner,$"{Lessons}/sessions/{f.Session}",assign));
        var item=(await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{p}")).GetProperty("item");(await Send(owner,$"{Lessons}/templates/{p}/archive",new LessonArchiveWrite(item.GetProperty("version").GetUInt32(),"نسخة مرجعية قديمة",Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.True((await owner.GetFromJsonAsync<JsonElement>($"{Lessons}/templates/{p}")).GetProperty("contentRetired").GetBoolean());
        var copy=await LessonId(await Send(owner,Lessons+"/exercises",ExerciseBody(f.Level) with{CopiedFromId=ex}));Assert.NotEqual(ex,copy);Assert.Equal("Draft",(await db.TrainingExercises.AsNoTracking().SingleAsync(e=>e.Id==copy)).State);
        var entity=await db.TrainingContentArchives.SingleAsync(a=>a.Id==archive);entity.Note="تعديل التاريخ";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());db.ChangeTracker.Clear();var sql=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"TrainingContentArchives\" WHERE \"Id\"={archive}"));Assert.Equal("23514",sql.SqlState);
        var actor=await db.Users.Where(u=>u.Email==DemoSeed.OwnerEmail).Select(u=>u.Id).SingleAsync();db.SessionLessonAssignments.Add(new(){Id=Guid.NewGuid(),AcademyId=DemoSeed.NogoomAcademyId,TrainingSessionId=f.Session,TemplateId=p,SportId=await db.TrainingLevels.Where(l=>l.Id==f.Level).Select(l=>l.SportId).SingleAsync(),Revision=2,ActorUserId=actor,ActorName="اختبار اصطناعي",RequestId=Guid.NewGuid(),RequestHash="forged-archived-assignment"});var invalid=await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());Assert.Equal("23514",Assert.IsType<Npgsql.PostgresException>(invalid.InnerException).SqlState);db.ChangeTracker.Clear();Assert.Equal(attendance,await db.PlayerAttendances.CountAsync());Assert.Equal(notices,await db.AcademyNotices.CountAsync());Assert.Equal(money,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));
    }
}
